    <style>
        :root {
            --color-green: #A8E6CF;
            --color-yellow: #EFFF54;
            --color-pink: #F4B6D1;
            --color-red: #FF8C8C;
            --color-cream: #FFF8F0;
            --color-lime: #D4ED68;
            --color-dark-green: #0D3B2E;
            --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-main);
            color: var(--color-dark-green);
            overflow-x: hidden;
            background-color: white;
        }

        /* Utility */
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
            position: relative;
            z-index: 2;
        }

        /* Wavy Separator */
        .wave-sep {
            width: 100%;
            height: 30px; /* Height of the wave */
            display: block;
            position: absolute;
            bottom: 0;
            left: 0;
            z-index: 10;
            fill: currentColor;
            transform: translateY(99%); /* Pull down to sit on the line */
        }

        .section-wrapper {
            position: relative;
            padding-bottom: 30px; /* Space for wave to overlap next section cleanly if needed, or just let it sit */
            overflow: hidden;
        }

        /* HEADER / HERO */
        header {
            background-color: var(--color-green);
            position: relative;
            min-height: 600px;
            display: flex;
            flex-direction: column;
            color: var(--color-dark-green);
        }

        nav {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 20px 40px;
            font-size: 14px;
            font-weight: 500;
        }

        .logo {
            font-weight: bold;
            font-size: 20px;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .nav-links {
            display: flex;
            gap: 25px;
        }

        .hero-content {
            flex-grow: 1;
            display: flex;
            justify-content: center;
            align-items: center;
            position: relative;
            padding-bottom: 60px;
        }

        .hero-text-box {
            background-color: rgba(255, 255, 255, 0.9);
            padding: 15px 30px;
            text-align: center;
            box-shadow: 0 4px 10px rgba(0,0,0,0.05);
            border-radius: 2px;
            max-width: 400px;
            margin-left: -100px; /* Offset slightly left as per image */
            z-index: 5;
        }

        .hero-text-box h1 {
            font-size: 32px;
            line-height: 1.2;
            font-weight: 500;
        }

        .hero-image {
            position: absolute;
            top: 50%;
            left: 55%;
            transform: translate(-50%, -50%);
            width: 450px;
            height: auto;
            object-fit: contain;
            filter: drop-shadow(0 10px 20px rgba(0,0,0,0.1));
            z-index: 4;
        }

        /* MARQUEE STRIP */
        .marquee-strip {
            background-color: var(--color-yellow);
            padding: 12px 0;
            overflow: hidden;
            white-space: nowrap;
            font-size: 16px;
            font-weight: 600;
            position: relative;
            z-index: 20;
            border-top: 2px solid var(--color-dark-green);
            border-bottom: 2px solid var(--color-dark-green); /* Visual separation implied by design style */
        }

        .marquee-strip span {
            display: inline-block;
            padding: 0 20px;
        }

        /* CARDS SECTION (PINK) */
        .cards-section {
            background-color: var(--color-pink);
            padding: 80px 0 100px;
            position: relative;
        }

        .cards-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 30px;
            align-items: start;
        }

        .card {
            position: relative;
            border-radius: 24px;
            overflow: hidden;
            aspect-ratio: 3/4;
            box-shadow: 0 5px 15px rgba(0,0,0,0.05);
            transition: transform 0.3s ease;
        }

        .card:hover {
            transform: translateY(-5px);
        }

        .card img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }

        .card-label {
            position: absolute;
            top: 15px;
            left: 15px;
            background-color: white;
            padding: 8px 16px;
            font-weight: 600;
            font-size: 18px;
            border-radius: 4px;
            box-shadow: 0 2px 5px rgba(0,0,0,0.05);
        }

        /* YELLOW SECTION (EMPTY) */
        .yellow-section {
            background-color: var(--color-yellow);
            height: 500px;
            position: relative;
        }

        /* RED SECTION (EMPTY) */
