            background-color: var(--color-cream);
            height: 550px;
            position: relative;
        }

        /* LIME SECTION (EMPTY) */
        .lime-section {
            background-color: var(--color-lime);
            height: 450px;
            position: relative;
        }

        /* PINK BOTTOM SECTION (EMPTY) */
        .pink-bottom-section {
            background-color: var(--color-pink);
            height: 300px;
            position: relative;
        }

        /* FORM SECTION (YELLOW) */
        .form-section {
            background-color: var(--color-yellow);
            padding: 120px 0 140px;
            text-align: center;
            position: relative;
        }

        .form-container {
            max-width: 500px;
            margin: 0 auto;
            display: flex;
            flex-direction: column;
            gap: 25px;
        }

        .form-row {
            display: flex;
            gap: 20px;
            justify-content: center;
        }

        .input-group {
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            flex: 1;
        }

        label {
            font-size: 13px;
            font-weight: 700;
            margin-bottom: 8px;
            color: var(--color-dark-green);
        }

        input {
            width: 100%;
            padding: 12px;
            border: none;
            border-radius: 4px;
            background: transparent;
            border-bottom: 2px solid transparent; 
            font-family: inherit;
            font-size: 14px;
        }

        input:focus {
            outline: none;
            border-bottom: 2px solid var(--color-dark-green);
        }

        .btn-submit {
            background-color: #EABCEB; /* Light purple/pink from screenshot */
            color: var(--color-dark-green);
            border: none;
            padding: 12px 35px;
            border-radius: 30px;
            font-weight: 700;
            cursor: pointer;
            align-self: center;
            transition: opacity 0.2s;
            font-size: 14px;
        }

        .btn-submit:hover {
            opacity: 0.9;
        }

        /* FOOTER */
        footer {
            background-color: var(--color-dark-green);
            height: 150px;
            position: relative;
            z-index: 20;
        }

        /* SVG Wave Styling */
        svg.wave {
            display: block;
            width: 100%;
            height: 30px;
            position: absolute;
            bottom: -1px; /* Overlap slightly to prevent gaps */
            left: 0;
            z-index: 10;
            fill: inherit; /* Will be overridden by inline style usually, but good for base */
            transform: scaleY(-1) rotate(180deg); /* Flip logic handled by path direction ideally, but this helps positioning */
        }

        /* Specific wave colors for transitions */
        .wave-to-yellow { fill: var(--color-yellow); }
        .wave-to-pink { fill: var(--color-pink); }
        .wave-to-red { fill: var(--color-red); }
        .wave-to-cream { fill: var(--color-cream); }
        .wave-to-lime { fill: var(--color-lime); }
        .wave-to-footer { fill: var(--color-dark-green); }

    </style>
